add("it4.q2", ("ऑक्सीकारक क्या हैं?", "ઑક્સિડેશનકર્તા એટલે શું?"),
    {0: ("जो पदार्थ दूसरे पदार्थों में ऑक्सीजन जोड़ सकते हैं (या उनसे हाइड्रोजन हटा सकते हैं) वे ऑक्सीकारक हैं।", "જે પદાર્થો બીજા પદાર્થોમાં ઑક્સિજન ઉમેરી શકે (કે તેમાંથી હાઇડ્રોજન દૂર કરી શકે) તે ઑક્સિડેશનકર્તા છે."),
     1: ("उदाहरण: क्षारीय पोटैशियम परमैंगनेट और अम्लीकृत पोटैशियम डाइक्रोमेट।", "ઉદાહરણ: આલ્કલાઇન પોટૅશિયમ પરમૅંગેનેટ અને ઍસિડિક પોટૅશિયમ ડાયક્રોમેટ.")})
add("it5.q1", ("क्या आप अपमार्जक का उपयोग कर बता सकते हैं कि कोई जल कठोर है अथवा नहीं?", "શું તમે ડિટર્જન્ટનો ઉપયોગ કરીને કહી શકો કે પાણી કઠિન છે કે નહિ?"),
    {0: ("नहीं।", "ના."), 1: ("अपमार्जक कठोर जल में भी झाग बनाते हैं और स्कम नहीं बनाते, इसलिए वे नहीं दिखा सकते कि जल कठोर है या नहीं। उस परीक्षण के लिए साबुन प्रयोग होता है।", "ડિટર્જન્ટ કઠિન પાણીમાં પણ ફીણ બનાવે છે અને સ્કમ બનાવતા નથી, તેથી તે બતાવી શકતા નથી કે પાણી કઠિન છે કે નહિ. એ કસોટી માટે સાબુ વપરાય છે.")})
add("it5.q2", ("लोग विभिन्न तरीकों से कपड़े धोते हैं। सामान्यतः साबुन लगाने के बाद लोग कपड़ों को पत्थर पर पटकते हैं, डंडे से पीटते हैं, ब्रश से रगड़ते हैं या मिश्रण को वाशिंग मशीन में विक्षुब्ध किया जाता है। कपड़ा साफ़ करने के लिए उसे विक्षुब्ध करना क्यों आवश्यक है?",
               "લોકો જુદી જુદી રીતે કપડાં ધૂએ છે. સામાન્ય રીતે સાબુ લગાવ્યા પછી લોકો કપડાંને પથ્થર પર પછાડે છે, ધોકાથી ધોકાવે છે, બ્રશથી ઘસે છે કે મિશ્રણને વૉશિંગ મશીનમાં હલાવવામાં આવે છે. કપડાં સાફ કરવા તેને હલાવવાં કેમ જરૂરી છે?"),
    {0: ("तैलीय मैल मिसेल के अंदर फँसा है, पर वह कपड़े से चिपका रहता है।", "તૈલી મેલ મિસેલની અંદર ફસાયેલો છે, પણ તે કપડાં સાથે ચોંટેલો રહે છે."),
     1: ("विक्षोभ मैल और मिसेल को कपड़े से अलग खींचता है ताकि उन्हें जल से धोया जा सके।", "હલાવવાથી મેલ અને મિસેલ કપડાંથી છૂટાં પડે છે જેથી તેમને પાણીથી ધોઈ શકાય.")})

# Exercises
mc("ex.q1", ("एथेन का आण्विक सूत्र C₂H₆ है। इसमें", "ઇથેનનું આણ્વીય સૂત્ર C₂H₆ છે. તેમાં"), ("एक C–C आबंध और छह C–H आबंध: 7।", "એક C–C બંધ અને છ C–H બંધ: 7."),
   {"6 covalent bonds.": (("6 सहसंयोजक आबंध हैं।", "6 સહસંયોજક બંધ છે."), ("C–C आबंध मत भूलिए।", "C–C બંધ ભૂલશો નહિ.")), "7 covalent bonds.": (("7 सहसंयोजक आबंध हैं।", "7 સહસંયોજક બંધ છે."), OK),
    "8 covalent bonds.": (("8 सहसंयोजक आबंध हैं।", "8 સહસંયોજક બંધ છે."), ("छह C–H आबंध और एक C–C आबंध हैं।", "છ C–H બંધ અને એક C–C બંધ છે.")), "9 covalent bonds.": (("9 सहसंयोजक आबंध हैं।", "9 સહસંયોજક બંધ છે."), ("फिर गिनिए: 6 + 1 = 7।", "ફરી ગણો: 6 + 1 = 7."))})
mc("ex.q2", ("ब्यूटेनोन चतुर्थ कार्बन यौगिक है जिसका प्रकार्यात्मक समूह है", "બ્યુટેનોન ચાર કાર્બનવાળું સંયોજન છે જેનો ક્રિયાશીલ સમૂહ છે"), ("अनुलग्न -ओन का अर्थ कीटोन समूह है।", "પ્રત્યય -ઓન એટલે કિટોન સમૂહ."),
   {"carboxylic acid.": (("कार्बोक्सिलिक अम्ल।", "કાર્બોક્સિલિક ઍસિડ."), ("अम्लों के नाम -ऑइक अम्ल पर खत्म होते हैं।", "ઍસિડનાં નામ -ઓઇક ઍસિડ થી પૂરાં થાય છે.")), "aldehyde.": (("ऐल्डिहाइड।", "આલ્ડિહાઇડ."), ("ऐल्डिहाइड के नाम -ऐल पर खत्म होते हैं।", "આલ્ડિહાઇડનાં નામ -આલ થી પૂરાં થાય છે.")),
    "ketone.": (("कीटोन।", "કિટોન."), OK), "alcohol.": (("ऐल्कोहॉल।", "આલ્કોહૉલ."), ("ऐल्कोहॉल के नाम -ऑल पर खत्म होते हैं।", "આલ્કોહૉલનાં નામ -ઑલ થી પૂરાં થાય છે."))})
mc("ex.q3", ("खाना बनाते समय यदि बर्तन की तली बाहर से काली हो रही है तो इसका मतलब है कि", "રસોઈ કરતી વખતે જો વાસણનું તળિયું બહારથી કાળું થતું હોય તો તેનો અર્થ એ છે કે"), ("अपूर्ण दहन से बिना जला कार्बन (कालिख) बचता है, जो बर्तन को काला करता है।", "અપૂર્ણ દહનથી ન સળગેલો કાર્બન (મેશ) બચે છે, જે વાસણને કાળું કરે છે."),
   {"the food is not cooked completely.": (("भोजन पूरी तरह नहीं पका है।", "ખોરાક પૂરો રંધાયો નથી."), ("कालापन बाहर की ओर है: यह ईंधन की कालिख है।", "કાળાશ બહારની બાજુએ છે: તે બળતણની મેશ છે.")),
    "the fuel is not burning completely.": (("ईंधन पूरी तरह नहीं जल रहा है।", "બળતણ સંપૂર્ણ રીતે સળગતું નથી."), OK), "the fuel is wet.": (("ईंधन गीला है।", "બળતણ ભીનું છે."), ("कारण कम वायु है, गीला ईंधन नहीं।", "કારણ ઓછી હવા છે, ભીનું બળતણ નહિ.")),
    "the fuel is burning completely.": (("ईंधन पूरी तरह जल रहा है।", "બળતણ સંપૂર્ણ રીતે સળગે છે."), ("पूर्ण दहन स्वच्छ नीली ज्वाला देता है और कालिख नहीं।", "સંપૂર્ણ દહન સ્વચ્છ વાદળી જ્યોત આપે છે અને મેશ નહિ."))})
add("ex.q4", ("CH₃Cl में आबंध निर्माण का उपयोग कर सहसंयोजक आबंध की प्रकृति समझाइए।", "CH₃Cl માં બંધ નિર્માણનો ઉપયોગ કરીને સહસંયોજક બંધનો સ્વભાવ સમજાવો."),
    {0: ("कार्बन के 4 संयोजकता इलेक्ट्रॉन हैं, हाइड्रोजन का 1 और क्लोरीन के 7।", "કાર્બનના 4 સંયોજકતા ઇલેક્ટ્રૉન છે, હાઇડ્રોજનનો 1 અને ક્લોરિનના 7."),
     1: ("कार्बन तीनों हाइड्रोजन परमाणुओं में से प्रत्येक के साथ इलेक्ट्रॉनों के एक युग्म की और क्लोरीन परमाणु के साथ एक युग्म की साझेदारी करता है: चार एकल सहसंयोजक आबंध।", "કાર્બન ત્રણેય હાઇડ્રોજન પરમાણુમાંથી દરેક સાથે ઇલેક્ટ્રૉનના એક યુગ્મની અને ક્લોરિન પરમાણુ સાથે એક યુગ્મની ભાગીદારી કરે છે: ચાર એકલ સહસંયોજક બંધ."),
     2: ("प्रत्येक परमाणु को स्थायी विन्यास मिलता है (H: 2 इलेक्ट्रॉन; C और Cl: 8)। कोई इलेक्ट्रॉन स्थानांतरित नहीं होता, इसलिए आयन नहीं बनते: आबंध सहसंयोजक हैं।", "દરેક પરમાણુને સ્થાયી રચના મળે છે (H: 2 ઇલેક્ટ્રૉન; C અને Cl: 8). કોઈ ઇલેક્ટ્રૉનની ફેરબદલી થતી નથી, તેથી આયનો બનતા નથી: બંધ સહસંયોજક છે.")})
add("ex.q5", ("इलेक्ट्रॉन-बिंदु संरचना बनाइए\n\n(a) एथेनॉइक अम्ल\n\n(b) H₂S\n\n(c) प्रोपेनोन\n\n(d) F₂", "ઇલેક્ટ્રૉન-બિંદુ રચના દોરો\n\n(a) ઇથેનોઇક ઍસિડ\n\n(b) H₂S\n\n(c) પ્રોપેનોન\n\n(d) F₂"),
    {0: ("(a) एथेनॉइक अम्ल, CH₃COOH: CH₃ कार्बन तीन H और दूसरे कार्बन के साथ एकल युग्मों की साझेदारी करता है; दूसरा कार्बन एक O के साथ द्वि-आबंध (दो युग्म) और –OH समूह के O के साथ एक युग्म की साझेदारी करता है, जो H के साथ एक युग्म साझा करता है।",
         "(a) ઇથેનોઇક ઍસિડ, CH₃COOH: CH₃ કાર્બન ત્રણ H અને બીજા કાર્બન સાથે એકલ યુગ્મની ભાગીદારી કરે છે; બીજો કાર્બન એક O સાથે દ્વિબંધ (બે યુગ્મ) અને –OH સમૂહના O સાથે એક યુગ્મની ભાગીદારી કરે છે, જે H સાથે એક યુગ્મ વહેંચે છે."),
     1: ("(b) H₂S: सल्फ़र प्रत्येक हाइड्रोजन के साथ एक युग्म की साझेदारी करता है और दो एकाकी युग्म रखता है।", "(b) H₂S: સલ્ફર દરેક હાઇડ્રોજન સાથે એક યુગ્મની ભાગીદારી કરે છે અને બે અબંધકારક યુગ્મ રાખે છે."),
     2: ("(c) प्रोपेनोन, CH₃COCH₃: बीच का कार्बन ऑक्सीजन के साथ द्वि-आबंध और दोनों CH₃ कार्बनों के साथ एकल युग्मों की साझेदारी करता है।", "(c) પ્રોપેનોન, CH₃COCH₃: વચ્ચેનો કાર્બન ઑક્સિજન સાથે દ્વિબંધ અને બંને CH₃ કાર્બન સાથે એકલ યુગ્મની ભાગીદારી કરે છે."),
     3: ("(d) F₂: दोनों फ़्लुओरीन परमाणु एक युग्म (एकल आबंध) की साझेदारी करते हैं; प्रत्येक तीन एकाकी युग्म रखता है।", "(d) F₂: બંને ફ્લોરિન પરમાણુ એક યુગ્મ (એકલ બંધ) ની ભાગીદારી કરે છે; દરેક ત્રણ અબંધકારક યુગ્મ રાખે છે."),
     4: ("प्रत्येक संरचना में हाइड्रोजन को छोड़कर हर परमाणु के चारों ओर आठ इलेक्ट्रॉन हैं; हाइड्रोजन के दो।", "દરેક રચનામાં હાઇડ્રોજન સિવાય દરેક પરમાણુની આસપાસ આઠ ઇલેક્ટ્રૉન છે; હાઇડ્રોજનની આસપાસ બે.")})
add("ex.q6", ("समजातीय श्रेणी क्या है? उदाहरण के साथ समझाइए।", "સમાનધર્મી શ્રેણી એટલે શું? ઉદાહરણ સાથે સમજાવો."),
    {0: ("समान क्रियात्मक समूह और समान रासायनिक गुणधर्मों वाले यौगिकों की श्रेणी, जिसके क्रमागत सदस्य –CH₂– इकाई से भिन्न होते हैं।", "સમાન ક્રિયાશીલ સમૂહ અને સમાન રાસાયણિક ગુણધર્મો ધરાવતાં સંયોજનોની શ્રેણી, જેના ક્રમિક સભ્યો –CH₂– એકમથી જુદા પડે છે."),
     1: ("उदाहरण: ऐल्केन CH₄, C₂H₆, C₃H₈, C₄H₁₀; या ऐल्कोहॉल CH₃OH, C₂H₅OH, C₃H₇OH।", "ઉદાહરણ: આલ્કેન CH₄, C₂H₆, C₃H₈, C₄H₁₀; કે આલ્કોહૉલ CH₃OH, C₂H₅OH, C₃H₇OH.")})
add("ex.q7", ("भौतिक एवं रासायनिक गुणधर्मों के आधार पर एथेनॉल एवं एथेनॉइक अम्ल में आप कैसे अंतर करेंगे?", "ભૌતિક અને રાસાયણિક ગુણધર્મોના આધારે ઇથેનૉલ અને ઇથેનોઇક ઍસિડ વચ્ચે તમે કેવી રીતે ભેદ પારખશો?"),
    {0: ("भौतिक: एथेनॉल की गंध सुखद है और गलनांक 156 K है; एथेनॉइक अम्ल की गंध सिरके जैसी है और यह 290 K पर जमता है। एथेनॉइक अम्ल नीले लिटमस को लाल करता है; एथेनॉल नहीं।", "ભૌતિક: ઇથેનૉલની ગંધ આનંદદાયક છે અને ગલનબિંદુ 156 K છે; ઇથેનોઇક ઍસિડની ગંધ સરકા જેવી છે અને તે 290 K એ થીજે છે. ઇથેનોઇક ઍસિડ વાદળી લિટમસને લાલ કરે છે; ઇથેનૉલ નહિ."),
     1: ("रासायनिक: एथेनॉइक अम्ल सोडियम हाइड्रोजनकार्बोनेट के साथ कार्बन डाइऑक्साइड देता है: {0}", "રાસાયણિક: ઇથેનોઇક ઍસિડ સોડિયમ હાઇડ્રોજન કાર્બોનેટ સાથે કાર્બન ડાયૉક્સાઇડ આપે છે: {0}"),
     2: ("एथेनॉल सोडियम हाइड्रोजनकार्बोनेट के साथ कोई गैस नहीं देता।", "ઇથેનૉલ સોડિયમ હાઇડ્રોજન કાર્બોનેટ સાથે કોઈ વાયુ આપતો નથી.")})
add("ex.q8", ("साबुन को जल में डालने पर मिसेल का निर्माण क्यों होता है? क्या एथेनॉल जैसे दूसरे विलायकों में भी मिसेल का निर्माण होगा?", "સાબુને પાણીમાં ઉમેરતાં મિસેલ કેમ બને છે? શું ઇથેનૉલ જેવા બીજા દ્રાવકોમાં પણ મિસેલ બનશે?"),
    {0: ("साबुन की लंबी कार्बन पूँछ जल में नहीं घुलती पर आयनिक सिरा घुलता है; इसलिए पूँछें अंदर की ओर इकट्ठी होती हैं और सिरे जल की ओर रहते हैं, जिससे मिसेल बनते हैं।", "સાબુની લાંબી કાર્બન પૂંછડી પાણીમાં ઓગળતી નથી પણ આયનીય છેડો ઓગળે છે; તેથી પૂંછડીઓ અંદરની બાજુ ભેગી થાય છે અને છેડા પાણી તરફ રહે છે, જેથી મિસેલ બને છે."),
     1: ("नहीं: कार्बन पूँछ भी एथेनॉल में घुल जाती है, इसलिए मिसेल नहीं बनते।", "ના: કાર્બન પૂંછડી પણ ઇથેનૉલમાં ઓગળી જાય છે, તેથી મિસેલ બનતાં નથી.")})
add("ex.q9", ("अधिकतर उपयोगों में ईंधन के रूप में कार्बन और उसके यौगिकों का प्रयोग क्यों होता है?", "મોટા ભાગના ઉપયોગોમાં બળતણ તરીકે કાર્બન અને તેનાં સંયોજનો કેમ વપરાય છે?"),
    {0: ("ये वायु में जलकर बहुत ऊष्मा और प्रकाश देते हैं।", "તે હવામાં સળગીને ઘણી ઉષ્મા અને પ્રકાશ આપે છે."),
     1: ("इनमें से कई स्वच्छ ज्वाला से जलते हैं, इनका भंडारण और परिवहन आसान है, और इनका ऊष्मीय मान उच्च है।", "તેમાંનાં ઘણાં સ્વચ્છ જ્યોતથી સળગે છે, તેમનો સંગ્રહ અને પરિવહન સહેલું છે, અને તેમનું કૅલરીમૂલ્ય ઊંચું છે.")})
add("ex.q10", ("कठोर जल को साबुन से उपचारित करने पर स्कम के निर्माण को समझाइए।", "કઠિન પાણીમાં સાબુ ઉમેરતાં સ્કમ કેવી રીતે બને છે તે સમજાવો."),
    {0: ("कठोर जल में कैल्सियम और मैग्नीशियम के लवण होते हैं।", "કઠિન પાણીમાં કૅલ્શિયમ અને મૅગ્નેશિયમના ક્ષાર હોય છે."),
     1: ("ये साबुन से अभिक्रिया करके वसीय अम्लों के अविलेय कैल्सियम और मैग्नीशियम लवण बनाते हैं, एक सफ़ेद अवक्षेप जिसे स्कम कहते हैं।", "તે સાબુ સાથે પ્રક્રિયા કરીને ફેટી ઍસિડના અદ્રાવ્ય કૅલ્શિયમ અને મૅગ્નેશિયમ ક્ષાર બનાવે છે, એક સફેદ અવક્ષેપ જેને સ્કમ કહે છે.")})
add("ex.q11", ("यदि आप लिटमस पत्र (लाल एवं नीला) से साबुन की जाँच करें तो आपका प्रेक्षण क्या होगा?", "જો તમે લિટમસપત્ર (લાલ અને વાદળી) થી સાબુની કસોટી કરો તો તમારું અવલોકન શું હશે?"),
    {0: ("साबुन का विलयन क्षारकीय होता है।", "સાબુનું દ્રાવણ બેઝિક હોય છે."), 1: ("यह लाल लिटमस को नीला करता है और नीले लिटमस को नहीं बदलता।", "તે લાલ લિટમસને વાદળી કરે છે અને વાદળી લિટમસને બદલતું નથી.")})
add("ex.q12", ("हाइड्रोजनीकरण क्या है? इसका औद्योगिक अनुप्रयोग क्या है?", "હાઇડ્રોજિનેશન એટલે શું? તેનો ઔદ્યોગિક ઉપયોગ શો છે?"),
    {0: ("निकेल उत्प्रेरक की उपस्थिति में असंतृप्त यौगिक में हाइड्रोजन का संकलन: {0}", "નિકલ ઉદ્દીપકની હાજરીમાં અસંતૃપ્ત સંયોજનમાં હાઇડ્રોજનનું ઉમેરણ: {0}"),
     1: ("इसका उपयोग वनस्पति तेलों को वनस्पति घी (ठोस वसा) में बदलने में होता है।", "તેનો ઉપયોગ વનસ્પતિ તેલને વનસ્પતિ ઘી (ઘન ચરબી) માં ફેરવવા થાય છે.")})
add("ex.q13", ("दिए गए हाइड्रोकार्बन में से कौन संकलन अभिक्रिया दर्शाते हैं: C₂H₆, C₃H₈, C₃H₆, C₂H₂ एवं CH₄।", "આપેલા હાઇડ્રોકાર્બનમાંથી કયા યોગશીલ પ્રક્રિયા દર્શાવે છે: C₂H₆, C₃H₈, C₃H₆, C₂H₂ અને CH₄."),
    {0: ("C₃H₆ (प्रोपीन) और C₂H₂ (एथाइन)।", "C₃H₆ (પ્રોપીન) અને C₂H₂ (ઇથાઇન)."), 1: ("ये असंतृप्त हैं (द्वि- और त्रि-आबंध); बाकी संतृप्त ऐल्केन हैं।", "તે અસંતૃપ્ત છે (દ્વિબંધ અને ત્રિબંધ); બાકીના સંતૃપ્ત આલ્કેન છે.")})
add("ex.q14", ("संतृप्त एवं असंतृप्त हाइड्रोकार्बन में विभेद करने के लिए एक परीक्षण बताइए।", "સંતૃપ્ત અને અસંતૃપ્ત હાઇડ્રોકાર્બન વચ્ચે ભેદ પારખવા માટે એક કસોટી જણાવો."),
    {0: ("इन्हें जलाइए: संतृप्त हाइड्रोकार्बन स्वच्छ नीली ज्वाला से जलते हैं; असंतृप्त कज्जली पीली ज्वाला से।", "તેમને સળગાવો: સંતૃપ્ત હાઇડ્રોકાર્બન સ્વચ્છ વાદળી જ્યોતથી સળગે છે; અસંતૃપ્ત ધુમાડાવાળી પીળી જ્યોતથી."),
     1: ("(असंतृप्त हाइड्रोकार्बन ब्रोमीन जल को रंगहीन भी करते हैं, संतृप्त नहीं।)", "(અસંતૃપ્ત હાઇડ્રોકાર્બન બ્રોમિન જળને રંગવિહીન પણ કરે છે, સંતૃપ્ત નહિ.)")})
add("ex.q15", ("साबुन की सफ़ाई प्रक्रिया की क्रियाविधि समझाइए।", "સાબુની સફાઈ ક્રિયાની કાર્યપદ્ધતિ સમજાવો."),
    {0: ("साबुन के अणु का एक आयनिक (जलरागी) सिरा और एक लंबी हाइड्रोकार्बन (जलविरागी) पूँछ होती है।", "સાબુના અણુનો એક આયનીય (જલઅનુરાગી) છેડો અને એક લાંબી હાઇડ્રોકાર્બન (જલવિરાગી) પૂંછડી હોય છે."),
     1: ("जल में साबुन के अणु मिसेल बनाते हैं: पूँछें बीच में तैलीय मैल में घुलती हैं और सिरे जल की ओर रहते हैं।", "પાણીમાં સાબુના અણુઓ મિસેલ બનાવે છે: પૂંછડીઓ વચ્ચે તૈલી મેલમાં ઓગળે છે અને છેડા પાણી તરફ રહે છે."),
     2: ("मिसेल जल में निलंबित रहते हैं; धोने और हिलाने से उनमें फँसा मैल बह जाता है।", "મિસેલ પાણીમાં નિલંબિત રહે છે; ધોવાથી અને હલાવવાથી તેમાં ફસાયેલો મેલ વહી જાય છે.")})

